    attributes = attributes.slice().sort((a: any, b: any) => {
        var v1 = a[query.order.replace(/^[-+]/, '')];
        var v2 = b[query.order.replace(/^[-+]/, '')];
        var reverse = query.order.charAt(0) === '-';
        var res = v1 > v2 ? 1 : (v1 < v2 ? -1 : 0);
        return reverse ? -res : res;
    });
    if (query.search != null) {
        attributes = attributes.filter((attribute: any) => attribute.key && attribute.key.indexOf(query.search) !== -1);
    }
